def truncate_words(text: str, limit: int) -> str:
    if not text or limit < 1:
        return ''

    words = text.split()
    result = []
    current_length = 0

    for word in words:
        if current_length + len(word) + (len(result) > 0) > limit:
            break
        result.append(word)
        current_length += len(word) + (len(result) > 0)

    return ' '.join(result)

