def seat_allocator(rows: int, per_row: int, requests: list) -> list:
    seating_chart = [[False] * per_row for _ in range(rows)]
    results = []

    for party_size in requests:
        seated = False
        for row in range(rows):
            if sum(seating_chart[row]) + party_size <= per_row:
                start_seat = seating_chart[row].index(False)
                for i in range(start_seat, start_seat + party_size):
                    seating_chart[row][i] = True
                results.append((row, start_seat))
                seated = True
                break
        if not seated:
            results.append(None)

