def reconcile(expected: dict, actual: dict) -> dict:
    missing = {}
    extra = {}
    matched = []

    for item, expected_qty in expected.items():
        actual_qty = actual.get(item, 0)
        if actual_qty < expected_qty:
            missing[item] = expected_qty - actual_qty
        elif actual_qty > expected_qty:
            extra[item] = actual_qty - expected_qty
        else:
            matched.append(item)

    for item, actual_qty in actual.items():
        if item not in expected:
            extra[item] = actual_qty

    matched.sort()
    return {'missing': missing, 'extra': extra, 'matched': matched}

